import{_ as p,c as e,o as r,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"困","description":"高島易斷 - 困","frontmatter":{"title":"困","description":"高島易斷 - 困"},"headers":[],"relativePath":"classics/takashima/047.md","filePath":"classics/takashima/047.md"}'),i={name:"classics/takashima/047.md"};function l(n,a,d,t,s,c){return r(),e("div",null,[...a[0]||(a[0]=[h('<h1 id="困" tabindex="-1">困 <a class="header-anchor" href="#困" aria-label="Permalink to “困”">​</a></h1><h2 id="困-1" tabindex="-1">困 <a class="header-anchor" href="#困-1" aria-label="Permalink to “困”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>困：亨，貞。大人吉，無咎。有言不信。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>“困”字，從木，在口中。木為陽之生氣，歷《坎》地則凋，逢《兌》金則刑，木斯困矣。必自《兌》而《坎》，轉而入《震》，《震》為春，為生，則木道乃亨。古來賢哲，其蒙難艱貞，不知幾經困苦，而始得亨通者，類如斯矣，故曰“大人吉，無咎”。“有言不信”者，謂當此困厄之際，身既不用，言何足重？惟宜簡默隱忍，以道自守，若復喋喋多言，反足招尤，其誰聽信乎！</p><h2 id="象辭" tabindex="-1">象辭 <a class="header-anchor" href="#象辭" aria-label="Permalink to “象辭”">​</a></h2><p>澤無水，困。君子以致命遂志。</p><h2 id="象辭注" tabindex="-1">象辭注 <a class="header-anchor" href="#象辭注" aria-label="Permalink to “象辭注”">​</a></h2><p>《井》《象》謂“木上有水”，取其可汲養也；《師》《象》謂“地中有水”，取其能容畜也；《困》之《象》曰“澤無水”，無水則無可汲養，亦無所容畜，而澤困矣。《坎》為水，亦為志，君子觀之，謂澤之不得水，猶士之不得志也。孔子曰，得之不得曰有命，命當其困，身可困，志不可奪也。譬如危城孤守，強敵環攻，內兵疲而外援絕，矢窮力盡，一戰身亡，以遂靖共之忠，斯不失見危授命之義也，是之謂“君子以致命遂志”。蓋命在天，志在我，時當困窮已極，無可奈何；命則聽之於天，志則盡夫在我，為道謀不為身謀，計百年不計一日。“困而不失其所亨”，惟君子能之。</p><h2 id="占斷" tabindex="-1">占斷 <a class="header-anchor" href="#占斷" aria-label="Permalink to “占斷”">​</a></h2><p>○　問時運：困窮至此，宜自安命。</p><p>○　問戰徵：是為孤城危急之時，惟竭力圖存，生死在所不計也。</p><p>○　問功名：名成則身難保，身存則名恐敗，惟善自處之。</p><p>○　問營商：資財既竭，時事又危，爻取往兇來吉，不如歸來，得可免困。</p><p>○　問婚姻：《彖》曰“剛揜”，男必夭命，女必守寡。易位為節，女必能守節成名。</p><p>○　問家宅：宅中有枯井，防致損命。</p><p>○　問訟事：不特訟不能直，且防因訟損命。</p><p>○　問行人：在外困苦不堪，且有生命之憂。</p><p>○　問疾病：腎水虧弱，症象已危。</p><p>○　問失物：墜入深潭之下，不可復得。</p><p>○　問六甲：生男。</p><h2 id="初六解" tabindex="-1">初六解 <a class="header-anchor" href="#初六解" aria-label="Permalink to “初六解”">​</a></h2><p>《坎》為臀，初處內卦之下，臀在人身之下，取《坎》下之象。《象傳》曰“澤無水”，為漏澤，臀之象亦漏下。《坎》於木為堅多心，“株木”為根在土上者，最在低下。人以臀為下，木以株為下，故為“臀困於株木”。凡人間居失業，謂之株守，可以為證。《兌》為谷，為幽，《坎》為入，為穴，為陷，陰爻亦為穴，“入於幽谷”，是陷《坎》之底。《兌》為見，《坎》為三歲，《坎》伏《兌》下，自初至四，歷三爻而《兌》始見，故曰“入於幽谷，三歲不覿”，皆從《坎》為隱伏取象。《象傳》以“幽不明”釋之，“幽”，暗也，人當困厄之來，宜審機度勢，擇地而蹈，冀可免厄。“困於株木，入於幽谷”，是困上加困也，亦因其不明所致也耳。</p><h2 id="初六佔" tabindex="-1">初六佔 <a class="header-anchor" href="#初六佔" aria-label="Permalink to “初六佔”">​</a></h2><p>○　問時運：厄運初來，漸入苦境，三年後可望順適。</p><p>○　問戰徵：兵陷險地，如司馬氏軍入葫蘆谷。</p><p>○　問營商：是販運材木生意，木在深谷，困於發運。</p><p>○　問功名：卑下之象，名必不顯。</p><p>○　問家宅：宅在深山，人跡罕到，宜於幽人。</p><p>○　問疾病：“株木”“幽谷”，有棺槨山丘之象，兇。</p><p>○　問婚姻：男家卑微，恐有遇人不淑之嘆。</p><p>○　問行人：三年後可歸。</p><p>○　問六甲：生男。</p><h2 id="初六案例" tabindex="-1">初六案例 <a class="header-anchor" href="#初六案例" aria-label="Permalink to “初六案例”">​</a></h2><p>明治十九年七月，橫濱友人某來，謂本年大孤兵庫等處，虎列喇疫病流行，幸東京橫濱皆得無恙，不料本月橫濱花町忽有一人患此症，爾來僕居鄰近，亦有傳染。深為憂慮，請為一筮，以決吉凶。筮得《困》之《兌》。</p><p>斷曰：《坎》為疾，為災，顯見有病。卦名曰《困》，《困》者難也。卦象“澤無水”，澤在水上，水必下漏，臀為孔，是必洩瀉之症。《兌》為秋，《坎》為冬，病起於秋，延及於冬，是時疫也。今佔初爻，爻辭曰“臀困於株木”，象近棺木，“入於幽谷”，象近葬穴，爻象頗兇；幸在初爻，病在初發，《彖傳》曰“困亨”，明示《困》之中，自有得亨之道也。“入於幽谷”，其殆示以避疫之地也；“幽谷”者，必是深山幽僻之所；“三歲不覿”者，自初至四，凡歷三爻，四爻入《兌》，《兌》為悅，為見，至《兌》則災脫，而心悅，可以出而相見也。三者為數之一變，暫則三歲，久則三月，皆取三也。玩此佔辭，君宜暫避於函根、伊香保等處，自可無患。某氏聞之大驚，即日起行，赴伊香保，果得平安無災。</p><h2 id="九二解" tabindex="-1">九二解 <a class="header-anchor" href="#九二解" aria-label="Permalink to “九二解”">​</a></h2><p>三、四、五三爻為剛，皆困於富貴者也。二與五應，二所云服飾祭享，與五爻同，五雖未言“酒食”，有祭享必有酒食，義亦可通。《坎》五曰“樽酒簋貳”，故有酒食象。《困》三陰三陽，卦自《乾》《坤》來，《乾》為衣，亦為朱，《坤》為裳，故有朱紱象。二動體為《萃》，《萃》二曰“利用禴”，故有享祀象。按：紱，蔽膝祭服；一作韍，《玉藻》曰：“一命組韍幽衡，再命赤韍幽衡，三命朱紱蔥衡。”二為大夫，故祭服用朱紱。二得乾氣，方膺大夫之命，故曰“方來”。“酒食”“朱紱”，謂膏梁足以傷生，文繡因而溺志，富貴之困人，即所謂死於安樂者是也。君子知之，不以酒食自養，不以朱紱自耀，而用諸祭祀，則俎豆馨香，孝孫有慶矣。“徵兇”者，以斯而徵，坎險在前，為三所阻，故“兇”；幸二居《坎》之中，故得“無咎”，是以《彖傳》即以“中有慶”釋之。</p><h2 id="九二佔" tabindex="-1">九二佔 <a class="header-anchor" href="#九二佔" aria-label="Permalink to “九二佔”">​</a></h2><p>○　問時運：爻象富貴，運非不佳，惜其不知撙節，反為富貴所困也。</p><p>○　問戰徵：防有因酒食誤事，遂致敗北，主將困而招褫緋之辱。</p><p>○　問營商：因商起家，膏梁文繡，足以榮亨，但再往則有兇也。</p><p>○　問功名：功名已顯，但恐為功名所困耳。</p><p>○　問疾病：是逸樂過甚，醉飽無度。宜禱。</p><p>○　問家宅：是富貴之家，住宅六神不安，宜虔祭告。無咎。</p><p>○　問婚姻：聘禮始備，彩禮方來，一說即成。</p><p>○　問六甲：生男。</p><h2 id="九二案例" tabindex="-1">九二案例 <a class="header-anchor" href="#九二案例" aria-label="Permalink to “九二案例”">​</a></h2><p>板垣伯佔氣運，得此爻，斷詞附載《地雷復》上爻，可以參看。</p><p>點擊進入《地雷復》上爻</p><h2 id="六三解" tabindex="-1">六三解 <a class="header-anchor" href="#六三解" aria-label="Permalink to “六三解”">​</a></h2><p>初、三、上三爻為柔，皆困於患難者也。柔爻象取草木，三與上應，三曰“蒺藜”，上曰“葛藟”，其象相近。三居《坎》之極，互體為《艮》，《艮》為小石，《象傳》謂“澤無水”，無水之地，泥土皆成砂磧，有石之象，故曰“困於石”。《坎》為蒺藜，蒺藜，草之有刺者也。軍中有鐵蒺藜，形似蒺藜，以鐵為之，布之於地，使敵不能前進。三爻陷下，乘二之剛，欲進不能，欲退不得，有似“據於蒺藜”。《坎》為宮為入，《兌》為少女，有妻之象，亦為見。三動體為《大過》，二曰“女妻”，五曰“老婦”，三則曰“棟撓”，則宮崩矣。宮之中已闃無人，何有於“女妻”，何有於“老婦”？故曰，“入於其宮，不見其妻”。《繫辭》謂“非所困而困，名必辱，非所據而據，身必危”，辱且危，故兇。《象傳》以“乘剛”釋據“蒺藜”，以三乘二之剛也，以“不祥”釋入其宮；以不見妻為兇也。</p><h2 id="六三佔" tabindex="-1">六三佔 <a class="header-anchor" href="#六三佔" aria-label="Permalink to “六三佔”">​</a></h2><p>○　問時運：命運尷尬，進退兩難，兇。</p><p>○　問戰徵：上布矢石，下設陷阱，前進則身多危，後退則膏已陷，大凶之象。</p><p>○　問功名：身將不保，奚以名為？</p><p>○　問營商：卜例，妻為財爻，宮即命宮，既喪其命，又失其財，大凶。</p><p>○　問疾病：《繫辭》曰“死期將至”，知病不可救也。</p><p>○　問婚姻：防有悼亡之戚。</p><p>○　問失物：不得。</p><p>○　問訟事：必散。</p><p>○　問六甲：生男。</p><h2 id="六三案例" tabindex="-1">六三案例 <a class="header-anchor" href="#六三案例" aria-label="Permalink to “六三案例”">​</a></h2><p>明治十九年七月，餘為避虎列喇時症，滯留函嶺木賀溫泉，東京物商藤田某，亦為避疫而來。止宿同館，出東京來簡示餘曰：僕親戚之婦某氏，忽罹時症，不知死生如何？敢請一佔。筮得《困》之《大過》。</p><p>斷曰：《繫辭》謂《困》三“非所困而困，非所據而據”，“死期將至，妻其可得見耶”？已明示其兇矣，不待斷而可知也。翌日得電報，此婦已死，計其時刻，昨當揲蓍之頃，適值入棺之候。三變為《大過》，《易》以《大過》為棺槨，其機更為靈妙。</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>《兌》為金，《坎》為車，九四《震》爻，辰在卯，上值房，石氏曰“房主車駕”，故有金車之象。四與初應，故相往來。“徐徐”，舒遲之狀；初居最下，四自外來，為二所間，疑懼不前，故曰“來徐徐”。四為諸侯，得乘金車，是亦乘剛而困於富貴者也。困於《坎》宮，困在身，困於富貴，困在心。四知初之困於柔，若不知已之困於剛也，乘此金車，徐徐來往，而不能以濟困，車殆馬煩，徒自苦耳，故“吝”。以陽居陰，為履不當位，然雖無二五之中，而自有二五之剛，惟剛足以自立，四得其剛，而二五復為推輓，庶幾相與有成，豈至終“困於金車”哉！故曰“有終”。是以《象傳》以“有與”釋之。</p><h2 id="九四佔" tabindex="-1">九四佔 <a class="header-anchor" href="#九四佔" aria-label="Permalink to “九四佔”">​</a></h2><p>○　問時運：運非不好，但地位不當，致多疑懼，未免為人所鄙。</p><p>○　問戰徵：遲緩不進，以致車轍靡亂，幸得救援，不至終敗。</p><p>○　問營商：辦事不力，致運載貨物，中途失陷，急救得全。</p><p>○　問功名：始困終亨。</p><p>○　問家宅：地位不當，為間分間隔，不能聯合，待遲緩乃佳。</p><p>○　問婚姻：緩緩可成。</p><p>○　問疾病：病勢遲緩，已非一日，想是馳驅勞頓致損。爻曰“有終”，其命永終矣。</p><p>○　問失物：想遺落車中，尋之可得。</p><p>○　問訟事：遷延已久，今始可罷。</p><p>○　問六甲：生女。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>友人某來，請佔氣運，筮得《困》之《坎》。</p><p>斷曰：君所問在氣運，而君意專在借貨，以借貨論。四下與初應，初爻柔為貧，四爻剛為富，當以初爻屬君，四爻屬貨者。在四固有意於初，間為二爻所阻，致四遲疑，不克速允，四亦未免有吝。為今之計，二與五應，必須挽五與二說開，則不相阻而相助，斯借貨終得許允也。後挽人向二說之，果得成就。</p><h2 id="九五解" tabindex="-1">九五解 <a class="header-anchor" href="#九五解" aria-label="Permalink to “九五解”">​</a></h2><p>《兌》為毀折，亦為刑人，劓截其鼻，刖斷其足，古之所謂肉刑也。五居尊位，為《困》之主，是主刑者也。至治之朝，政簡刑清，君民相得，不為無恥之倖免，而為有恥之且格，斯可謂之得志矣。若惟恃劓刖之用，自矜明察，上邀受服之榮，下蒙赭衣之苦，檻車毳衣，徒見其困而已，故“困於赤紱”，系諸“劓刖”之下也。《兌》為口，“乃徐有說，”弼教之道，以漸而入，故曰“徐”。知用刑之不得其志，則齊之以刑，不如道之以德，此為教化之漸；而仁義之流，非獨肌膚之效也。道惟在於中直，中則無偏，直者無枉，以此中直而臨民，即以此中直而事神，則服赤紱而薦馨香，而來亨來格，降爾遐福，斯困於人者，必不困於天矣，故曰“利用祭祀”。《象傳》以“受福”釋之，九五陽爻屬《乾》，《乾》為福，福自《乾》來，既所謂自天受之也。</p><h2 id="九五佔" tabindex="-1">九五佔 <a class="header-anchor" href="#九五佔" aria-label="Permalink to “九五佔”">​</a></h2><p>○　問時運：命運剛強，剛則必折，防有損傷。作事宜籌度舒遲，乃可變禍為福。</p><p>○　問營商：貨物底面，防有潰爛損傷，須拆看收拾，徐徐出售，無咎。</p><p>○　問功名：防富貴後，致有刑傷，宜禱。</p><p>○　問戰徵：主敗，須徐緩收兵，可圖後勝。</p><p>○　問家宅：家業卻好，主家人有爛鼻跛足之患，宜祈禱。</p><p>○　問疾病：病在頭足，徐徐調養，求神醫治，可愈。</p><p>○　問婚姻：主有殘疾，始不合意，後得完好。</p><p>○　問訟事：防有刑獄之災，須徐徐辯白，方可免罷。</p><p>○　問行人：在外有災，宜禱，後可得意而歸。</p><p>○　問失物：必有破傷，久後可以尋獲。</p><p>○　問六甲：生女。</p><h2 id="九五案例" tabindex="-1">九五案例 <a class="header-anchor" href="#九五案例" aria-label="Permalink to “九五案例”">​</a></h2><p>縉紳某來，請佔氣運，筮得《困》之《解》。</p><p>斷曰：“劓”，謂截其鼻也，“刖”，謂斷其足也。“困於赤紱”，謂富貴而受困也，“乃徐有說，利用祭祀”，謂舒緩開道，利用酒食以和解也。想足下於朋友之間，嚴厲過甚，令人面目無光，無可退步。今彼故與足下為難，於廣眾之地，乘足下文繡而來，大施殘辱，是所謂“困於赤紱”也。足下須降心下氣，徐徐辯說，或復置酒立盟，誓不復記舊恨，乃可轉禍為福，否則冤冤相尋，無有已時也。足下佔得《困》五爻，爻象如此，餘就佔而斷，合與不合，足下當自知之。</p><h2 id="上六解" tabindex="-1">上六解 <a class="header-anchor" href="#上六解" aria-label="Permalink to “上六解”">​</a></h2><p>《兌》為附決，孔穎達曰，“附決為果瓜之屬”，故有葛藟之象。上六居《兌》之極，與初三併為陰爻，故象取草木，是謂困於患難者也。上六去《坎》己遠，似可出幽谷而遷喬木矣，乃重柔不中，不能自立，如葛藟之附物蔓延，搖宕不安，故臲卼。臲卼，不安之狀；一作杌隉，文異而音義通也。欲脫此困，非動不可，然動則不能無悔，故曰“動悔”；惟知其動之有悔，而審慎以出之，正將因悔以求全，轉以有悔而可往。蓋道以窮而始達，境由苦而得甘，此遷善所以必先悔過也。由此以往，往無不吉，故曰“吉”。《象傳》一則以“未當”釋之，謂其為柔所困，柔“未當也”；一則以“吉行”釋之，謂其以動得悔，悔亦吉也。</p><h2 id="上六佔" tabindex="-1">上六佔 <a class="header-anchor" href="#上六佔" aria-label="Permalink to “上六佔”">​</a></h2><p>○　問時運：目下苦運已終，本可脫難，緣其心神不安，未能立作變計，一旦改悔，即可獲吉。</p><p>○　問功名：困窮既久，行將風雲變動，一舉成名。吉。</p><p>○　問營商：“困於葛藟”，必是包紮貨物，久不得售，今當時價發動，即可獲利。吉。</p><p>○　問戰徵：爻曰“徵吉”，《象》曰“吉行”，其中雖有災悔，定可因悔得吉也。</p><p>○　問疾病：此病必纏綿已久，神志不安，當遷地靜養，自然痊癒。</p><p>○　問家宅：此宅已舊，藤葛叢生，棟柱傾斜，宜動工改作，乃吉。</p><p>○　問婚姻：其中防有瓜葛未清，看其動靜如何，一動之後，斯可成就。吉。</p><p>○　問訟事：纏繞未休，致多臲卼，必待斷結，乃可無事。</p><p>○　問行人：一時被事糾纏，難歸。</p><p>○　問失物：被物繞住，不見，必移動後，乃可尋獲。</p><p>○　問六甲：生女。</p><h2 id="上六案例" tabindex="-1">上六案例 <a class="header-anchor" href="#上六案例" aria-label="Permalink to “上六案例”">​</a></h2><p>友人某來，請佔氣運，筮得《困》之《訟》。</p><p>斷曰：《大象》曰“澤無水”，無水則物不得滋養，而無以生髮，猶人無財而無以生活，為困窮之甚也。今佔得上爻，上爻《困》之終，本可脫困，《困》卦體柔弱過甚，如葛藟之施木，不能自立，以致飄蕩不安，若能決然思奮，動而有為，故曰“徵吉”。所謂“徵吉”，利於出行，不利坐守。足下宜乎遵此斷而行，後運正佳。</p>',116)])])}const m=p(i,[["render",l]]);export{b as __pageData,m as default};
